"use client";
/** Countries → provinces data (generated by scripts/build-geo.mjs) and location detection for profile forms. */
export interface GeoCountry { c: string; n: string; s: string[] }

let geoPromise: Promise<GeoCountry[]> | null = null;
/** ~95 KB of JSON, loaded on demand so it stays out of the main bundle. */
export function loadGeo(): Promise<GeoCountry[]> {
  geoPromise ??= import("./geo.json").then((m) => m.default as GeoCountry[]);
  return geoPromise;
}

const norm = (s: string) =>
  s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase()
    .replace(/\b(region|province|state|oblast|viloyati|district|county|prefecture|governorate|republic of|city)\b/g, "").replace(/[^a-z0-9]/g, "");

/** Best match for a detected subdivision name among a country's provinces ("" if none is close). */
export function matchProvince(provinces: string[], detected: string) {
  const d = norm(detected);
  if (!d) return "";
  // Exact name first: "Tashkent" (the city) and "Tashkent Region" are different provinces.
  const exact = provinces.find((p) => p.toLowerCase() === detected.trim().toLowerCase());
  if (exact) return exact;
  return provinces.find((p) => norm(p) === d) ?? provinces.find((p) => norm(p).includes(d) || d.includes(norm(p))) ?? "";
}

export interface DetectedLocation { country: string; province: string; city: string; lat: number | null; lng: number | null; precise: boolean }

/**
 * Detects the user's country / province / city.
 *  • precise = true asks the browser for GPS permission;
 *  • precise = false uses the approximate network location (no permission prompt).
 * Coordinates are only used for this lookup (BigDataCloud's free client-side reverse-geocoding API) and are not stored.
 */
export async function detectLocation(precise: boolean): Promise<DetectedLocation> {
  let coords: { lat: number; lng: number } | null = null;
  if (precise) {
    coords = await new Promise((resolve, reject) => {
      if (!("geolocation" in navigator)) return reject(new Error("Location isn't available on this device."));
      navigator.geolocation.getCurrentPosition(
        (p) => resolve({ lat: p.coords.latitude, lng: p.coords.longitude }),
        () => reject(new Error("Location permission was not granted. Pick your country and province from the lists instead.")),
        { enableHighAccuracy: false, timeout: 10_000, maximumAge: 600_000 },
      );
    });
  }
  const url = new URL("https://api.bigdatacloud.net/data/reverse-geocode-client");
  if (coords) { url.searchParams.set("latitude", String(coords.lat)); url.searchParams.set("longitude", String(coords.lng)); }
  url.searchParams.set("localityLanguage", "en");
  const res = await fetch(url, { signal: AbortSignal.timeout(8000) }).catch(() => null);
  if (!res?.ok) throw new Error("Couldn't look up your location. Pick your country and province from the lists instead.");
  const d = (await res.json()) as { countryCode?: string; countryName?: string; principalSubdivision?: string; city?: string; locality?: string; latitude?: number; longitude?: number };
  const geo = await loadGeo();
  const country = geo.find((g) => g.c === d.countryCode);
  if (!country) throw new Error("Couldn't recognise your country. Pick it from the list instead.");
  return {
    country: country.n, province: matchProvince(country.s, d.principalSubdivision ?? ""), city: d.city || d.locality || "",
    lat: coords?.lat ?? d.latitude ?? null, lng: coords?.lng ?? d.longitude ?? null, precise,
  };
}
